"""Literal single-cell intrinsic contributions for the CapabilityTable allocator."""
from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
script=defs+'''
for(const language of ['ko','en']){lang=language;const source=document.createElement('div');source.innerHTML=capabilities();for(const [index,cell] of [...source.querySelectorAll('th,td')].entries())for(const mode of ['min-content','max-content']){const f=document.createElement('div');f.className='intrinsic';f.dataset.id=language+'-'+index+'-'+mode;const table=document.createElement('table');table.className='capability-table';table.style.width=mode;const group=document.createElement(cell.tagName==='TH'?'thead':'tbody');const row=document.createElement('tr');row.append(cell.cloneNode(true));group.append(row);table.append(group);f.append(table);document.body.append(f)}}
document.getElementById('record-cell-intrinsics').onclick=async()=>{await document.fonts.ready;const samples=[...document.querySelectorAll('.intrinsic')].map(f=>{const cell=f.querySelector('th,td'),s=getComputedStyle(cell);return{id:f.dataset.id,width:cell.getBoundingClientRect().width,text:cell.textContent,padding:s.padding,font:s.font,descendants:[...cell.querySelectorAll('*')].map(e=>{const q=e.getBoundingClientRect(),c=getComputedStyle(e);return{tag:e.tagName,text:e.textContent,width:q.width,font:c.font,gap:c.gap,flex:c.flex,minWidth:c.minWidth}})}});const os=new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac';const res=await fetch('/evidence/preflight-capabilitytable-'+os+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,kind:'single-cell-intrinsics',samples})});if(!res.ok)throw Error('Record failed');document.getElementById('record-cell-intrinsics').textContent='Cell intrinsic contributions recorded'};
'''
(o/'capabilitytable-intrinsics.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityTable cell contributions · original isolation</title><link rel="stylesheet" href="capabilitytable-original.css"><style>.intrinsic{position:absolute;visibility:hidden;left:30px;top:40px;width:1200px}</style><button id="record-cell-intrinsics">Record cell intrinsic contributions</button><script>'+script+'</script>')
print('Literal single-cell min/max80 prepared')
